// The expected values in this file were generated by running the Python
// reference implementation (src/rag_mcp/sparse.py) directly, so these tests
// lock bit-for-bit behavioral parity rather than just self-consistency.

func TestBlake2sKnownVector(t *testing.T) {
	digest := blake2sDigest([]byte("abc"), 32, [8]byte{})
	got := hex.EncodeToString(digest)
	const want = "508c5e8c327c14e2e1a72ba34eeb452f37458b209ed63a294d999b4c86675982"
	if got != want {
		t.Fatalf("blake2s-256(abc) = %s, want %s", got, want)
	}
}

func TestBlake2sPersonalizedTokenIndicesMatchPython(t *testing.T) {
	cases := map[string]uint32{
		"star":    844_488_336,
		"索引":      3_981_411_649,
		"rrf":     3_178_323_965,
		"原文":      193_031_688,
		"v2":      2_353_496_066,
		"block-块": 366_232_988,
	}
	for token, want := range cases {
		if got := tokenIndex(token); got != want {
			t.Errorf("tokenIndex(%q) = %d, want %d", token, got, want)
		}
	}
}

func TestTokenizeMatchesPython(t *testing.T) {
	cases := []struct {
		text string
		want []string
	}{
		{
			"索引 V2 出现 RRF，文档原文片段",
			[]string{"索", "引", "索引", "v2", "出", "现", "出现", "rrf", "文", "档",
				"原", "文", "片", "段", "文档", "档原", "原文", "文片", "片段"},
		},
		{
			"RRF RRF 文档原文片段",
			[]string{"rrf", "rrf", "文", "档", "原", "文", "片", "段", "文档", "档原", "原文", "文片", "片段"},
		},
		{
			"RRF 怎么处理",
			[]string{"rrf", "怎", "么", "处", "理", "怎么", "么处", "处理"},
		},
		{"", []string{}},
		{
			"ABC abc Ångström Straße ＲＲＦ　全角",
			[]string{"abc", "abc", "ngstr", "m", "strasse", "rrf", "全", "角", "全角"},
		},
		{
			"混合 Mix-01 test_case.v2 接口",
			[]string{"混", "合", "混合", "mix", "01", "test", "case", "v2", "接", "口", "接口"},
		},
		{"ı İ I ı", []string{"ı", "i", "i", "ı"}},
		{"ϓ ϔ ẚ ﬃ", []string{"a", "ffi"}},
		{"İstanbul", []string{"i", "stanbul"}},
		{"Ⅻ ⑬ ㈱", []string{"xii", "13", "株"}},
		{"A\u030A ring", []string{"ring"}},
		{
			"行政区块 0xFF 12.5%",
			[]string{"行", "政", "区", "块", "行政", "政区", "区块", "0xff", "12", "5"},
		},
	}
	for _, testCase := range cases {
		got := Tokenize(testCase.text)
		if !reflect.DeepEqual(got, testCase.want) {
			t.Errorf("Tokenize(%q)\n got: %q\nwant: %q", testCase.text, got, testCase.want)
		}
	}
}

